#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> words(n);
    for (auto &w : words) cin >> w;
    stable_sort(words.begin(), words.end(), [](const string &x, const string &y) { return x.size() < y.size(); });
    // best[w] = longest chain ending at w; every predecessor is w with one letter deleted.
    unordered_map<string, int> best;
    int answer = 0;
    for (const string &w : words) {
        int value = 0;
        for (size_t i = 0; i < w.size(); i++) {
            auto it = best.find(w.substr(0, i) + w.substr(i + 1));
            if (it != best.end()) value = max(value, it->second);
        }
        best[w] = value + 1;
        answer = max(answer, value + 1);
    }
    cout << answer << "\n";
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = sc.next();
        Arrays.sort(words, Comparator.comparingInt(String::length));
        // best[w] = longest chain ending at w; every predecessor is w with one letter deleted.
        Map<String, Integer> best = new HashMap<>();
        int answer = 0;
        for (String w : words) {
            int value = 0;
            for (int i = 0; i < w.length(); i++)
                value = Math.max(value, best.getOrDefault(w.substring(0, i) + w.substring(i + 1), 0));
            best.put(w, value + 1);
            answer = Math.max(answer, value + 1);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	words := make([]string, n)
	for i := range words {
		fmt.Fscan(in, &words[i])
	}
	sort.SliceStable(words, func(i, j int) bool { return len(words[i]) < len(words[j]) })
	// best[w] = longest chain ending at w; every predecessor is w with one letter deleted.
	best := map[string]int{}
	answer := 0
	for _, w := range words {
		value := 0
		for i := 0; i < len(w); i++ {
			value = max(value, best[w[:i]+w[i+1:]])
		}
		best[w] = value + 1
		answer = max(answer, value+1)
	}
	fmt.Println(answer)
}
